div.script:
(function () {
  var modal = document.getElementById('vrTeamModal');
  if (!modal) { return; }
  var list = modal.querySelector('[data-team-support]');
  var fResp = modal.querySelector('[data-team-form=responsible]');
  var fAdd = modal.querySelector('[data-team-form=add]');
  var fRem = modal.querySelector('[data-team-form=remove]');
  var names = {};
  Array.prototype.forEach.call(fAdd.querySelectorAll('option'), function (o) { if (o.value) { names[o.value] = o.textContent; } });
  var opener = null;
  function close() { modal.classList.remove('open'); if (opener) { opener.focus(); } }
  function open(btn) {
    opener = btn;
    var ref = btn.dataset.ref, base = '/verifier/verifications/' + encodeURIComponent(ref) + '/team/';
    fResp.action = base + 'assign'; fAdd.action = base + 'add'; fRem.action = base + 'delete';
    modal.querySelector('[data-team-name]').textContent = btn.dataset.name || '';
    var sel = fResp.querySelector('select'); sel.value = btn.dataset.resp || '';
    var sup = (btn.dataset.support || '').split(',').filter(Boolean);
    list.innerHTML = '';
    if (!sup.length) {
      var li = document.createElement('li'); li.className = 'vr-muted small'; li.textContent = 'Sin técnicos de apoyo.'; list.appendChild(li);
    }
    sup.forEach(function (r) {
      var li = document.createElement('li'); li.className = 'vr-member';
      var n = names[r] || r;
      li.innerHTML = 'Apoyo Quitar';
      li.querySelector('.vr-av').textContent = n.split(' ').slice(0, 2).map(function (w) { return w[0] || ''; }).join('').toUpperCase();
      li.querySelector('b').textContent = n;
      li.querySelector('button').addEventListener('click', function () { fRem.querySelector('[name=technician_ref]').value = r; fRem.submit(); });
      list.appendChild(li);
    });
    var addSel = fAdd.querySelector('select');
    Array.prototype.forEach.call(addSel.options, function (o) { if (o.value) { o.hidden = o.value === btn.dataset.resp || sup.indexOf(o.value) !== -1; } });
    addSel.value = '';
    addSel.disabled = !btn.dataset.resp; fAdd.querySelector('button').disabled = !btn.dataset.resp;
    modal.classList.add('open');
    sel.focus();
  }
  document.querySelectorAll('.js-team-open').forEach(function (b) { b.addEventListener('click', function (ev) { ev.preventDefault(); open(b); }); });
  modal.querySelectorAll('[data-team-close]').forEach(function (b) { b.addEventListener('click', close); });
  modal.addEventListener('click', function (e) { if (e.target === modal) { close(); } });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && modal.classList.contains('open')) { close(); } });
})();

(function(){
  function val(name){
    var el = document.querySelector('[name="'+name+'"]');
    if(!el) return 0;
    var n = parseFloat((el.value||'').replace(',','.'));
    return isNaN(n) ? 0 : n;
  }
  function recompute(){
    var sent = val('weight_sent_lb'), plant = val('weight_plant_lb'), trash = val('trash_lb');
    var ow = plant - sent;
    var factor = sent ? plant / sent : 0;
    var net = Math.max(0, plant - trash);
    var o=document.getElementById('svOverweight'), f=document.getElementById('svFactor'), n=document.getElementById('svNet');
    if(o) o.textContent = ow.toFixed(2) + ' lb';
    if(f) f.textContent = factor.toFixed(4);
    if(n) n.textContent = net.toFixed(2) + ' lb';
  }
  ['weight_sent_lb','weight_plant_lb','trash_lb'].forEach(function(nm){
    var el = document.querySelector('[name="'+nm+'"]');
    if(el){ el.addEventListener('input', recompute); }
  });
})();

(function(){
  var body = document.getElementById('svLinesBody');
  if(!body) return;
  function fnum(name){ var el=document.querySelector('[name="'+name+'"]'); if(!el) return 0; var x=parseFloat((el.value||'').replace(',','.')); return isNaN(x)?0:x; }
  function setTxt(id,t){ var el=document.getElementById(id); if(el) el.textContent=t; }
  function recompute(){
    var a=0,b=0,c=0;
    Array.prototype.forEach.call(body.querySelectorAll('tr'), function(tr){
      var w=tr.querySelector('[name$="_weight"]'), cl=tr.querySelector('[name$="_class"]');
      var wv=w?parseFloat((w.value||'').replace(',','.')):0; if(isNaN(wv)) wv=0;
      var cv=cl?cl.value:'a';
      if(cv==='a') a+=wv; else if(cv==='b') b+=wv; else c+=wv;
    });
    var total=a+b+c;
    var plant=fnum('weight_plant_lb'), trash=fnum('trash_lb');
    var net=Math.max(0, plant-trash);
    setTxt('svTotal', total.toFixed(2)+' lb');
    setTxt('svYield', (net? total/net*100:0).toFixed(2)+' %');
    setTxt('svClassA', (total? a/total*100:0).toFixed(2)+' %');
    setTxt('svClassB', (total? b/total*100:0).toFixed(2)+' %');
    setTxt('svClassC', (total? c/total*100:0).toFixed(2)+' %');
  }
  Array.prototype.forEach.call(body.querySelectorAll('input'), function(el){ el.addEventListener('input', recompute); });
  ['weight_plant_lb','trash_lb'].forEach(function(nm){ var el=document.querySelector('[name="'+nm+'"]'); if(el) el.addEventListener('input', recompute); });
  recompute();
})();

(function(){
  var input=document.getElementById('svPhotoInput');
  var gallery=document.getElementById('svPhotoGallery');
  var addBtn=document.getElementById('svPhotoAdd');
  if(!gallery) return;
  var ref=gallery.getAttribute('data-ref');
  var token=(document.querySelector('input[name="csrf_token"]')||{}).value||'';

  // Modal de confirmación (reemplaza al confirm() del navegador).
  var modal=document.getElementById('svPhotoConfirm');
  var okBtn=document.getElementById('svPhotoConfirmOk');
  var pending=null;
  function openModal(fn){ pending=fn; if(modal) modal.classList.add('open'); }
  function closeModal(){ pending=null; if(modal) modal.classList.remove('open'); }
  if(modal){
    Array.prototype.forEach.call(modal.querySelectorAll('[data-photo-cancel]'), function(b){ b.addEventListener('click', closeModal); });
    modal.addEventListener('click', function(e){ if(e.target===modal) closeModal(); });
  }
  if(okBtn) okBtn.addEventListener('click', function(){ var fn=pending; closeModal(); if(fn) fn(); });

  // Eliminar (inmediato) las fotos ya adjuntas, con confirmación en modal.
  Array.prototype.forEach.call(gallery.querySelectorAll('[data-remove-attached]'), function(btn){
    btn.addEventListener('click', function(){
      openModal(function(){
        var id=btn.getAttribute('data-id');
        var fd=new FormData(); fd.append('csrf_token', token);
        fetch((gallery.getAttribute('data-del-base')||('/verifier/verifications/'+ref))+'/photos/'+id+'/delete', {method:'POST', body:fd})
          .then(function(r){ if(r.ok){ var t=btn.closest('.sv-photo-thumb'); if(t) t.remove(); }
                             else { window.alert('No se pudo eliminar la foto.'); } });
      });
    });
  });

  // Agregar fotos nuevas (acumula y previsualiza sin tocar las adjuntas).
  if(input && addBtn && typeof DataTransfer!=='undefined'){
    var dt=new DataTransfer();
    addBtn.addEventListener('click', function(){ input.click(); });
    input.addEventListener('change', function(){
      Array.prototype.forEach.call(input.files, function(f){ if(/^image\//.test(f.type)) dt.items.add(f); });
      input.files=dt.files; renderNew();
    });
    function renderNew(){
      Array.prototype.forEach.call(gallery.querySelectorAll('.sv-photo-new'), function(nd){ nd.remove(); });
      Array.prototype.forEach.call(dt.files, function(f, i){
        var wrap=document.createElement('div'); wrap.className='sv-photo-thumb sv-photo-new';
        var img=document.createElement('img'); img.src=URL.createObjectURL(f); wrap.appendChild(img);
        var del=document.createElement('button'); del.type='button'; del.className='sv-photo-del'; del.textContent='×';
        del.addEventListener('click', function(){
          var ndt=new DataTransfer();
          Array.prototype.forEach.call(dt.files, function(ff,j){ if(j!==i) ndt.items.add(ff); });
          dt=ndt; input.files=dt.files; renderNew();
        });
        wrap.appendChild(del);
        gallery.appendChild(wrap);
      });
    }
  }
})();

(function(){
  function init(){
    function cerrar(){
      document.querySelectorAll('.sv-info-modal.open').forEach(function(m){
        m.classList.remove('open');
      });
    }
    document.querySelectorAll('.js-verif-info').forEach(function(b){
      b.addEventListener('click', function(ev){
        ev.preventDefault(); ev.stopPropagation();
        var m = document.getElementById(b.getAttribute('data-verif'));
        if(m){ cerrar(); m.classList.add('open'); }
      });
    });
    document.querySelectorAll('.js-verif-cerrar').forEach(function(b){
      b.addEventListener('click', function(ev){ ev.preventDefault(); cerrar(); });
    });
    // Clic en el fondo cierra; clic dentro de la tarjeta, no.
    document.querySelectorAll('.sv-info-modal').forEach(function(m){
      m.addEventListener('click', function(ev){ if(ev.target === m){ cerrar(); } });
    });
    // Escape cierra la ficha, pero solo si el visor del PDF no está abierto:
    // si no, una sola tecla cerraría las dos capas de golpe.
    document.addEventListener('keydown', function(ev){
      if(ev.key !== 'Escape') return;
      var visor = document.getElementById('certModal');
      if(visor && visor.classList.contains('open')) return;
      cerrar();
    });
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', init); }
  else { init(); }
})();

t.script:
(function(){
  // Los avisos de "pendiente de verificación" son informativos y el
  // estado sigue visible en cada compra, así que se desvanecen solos.
  // Los de "ya puedes concluir" no: ahí hay una acción por hacer.
  var autos = document.querySelectorAll('.sv-alert--auto');
  if(!autos.length){ return; }
  setTimeout(function(){
    autos.forEach(function(el){
      el.classList.add('sv-alert--fading');
      setTimeout(function(){ el.style.display = 'none'; }, 600);
    });
  }, 7000);
})();

